with p as (select id from liq_proveedores where nombre='MUFG')
update liq_proveedores set email_patron=null, email_patron_fuente='no se halló patrón corroborado por una dirección publicada · confianza: n/a',
 canales_publicos='[{"canal": "Comunicado oficial PoC JGB repo en Canton (MUFG holding, 13-ago-2026)", "valor": "https://www.mufg.jp/dam/pressrelease/2026/pdf/news-20260813-002_en.pdf", "fuente": "https://www.mufg.jp/dam/pressrelease/2026/pdf/news-20260813-002_en.pdf"}, {"canal": "Comunicado PoC Canton – Mitsubishi UFJ Trust and Banking (inglés)", "valor": "https://www.tr.mufg.jp/english/pressreleases/pdf/20260813_2.pdf", "fuente": "https://www.tr.mufg.jp/english/pressreleases/pdf/20260813_2.pdf"}, {"canal": "Comunicado PoC Canton – MUFG Bank global newsroom", "valor": "https://www.bk.mufg.jp/global/newsroom/news2026/pdf/newse0813_1.pdf", "fuente": "https://www.bk.mufg.jp/global/newsroom/news2026/pdf/newse0813_1.pdf"}, {"canal": "Prensa / Corporate Communications APAC (MUFG Bank) – único buzón público verificado", "valor": "corpcomms@sg.mufg.jp", "fuente": "https://www.bk.mufg.jp/global/globalnetwork/asiapacific/anncts/index.html"}, {"canal": "Sitio oficial Progmat (progmat.co.jp; dominio no verificado en esta sesión por bloqueo DNS)", "valor": null, "fuente": "https://www.datachain.jp/news/partnership-with-progmat-avalanche"}, {"canal": "MUFG Innovation Partners (CVC del grupo, inversor en Securitize)", "valor": "https://www.ip.mufg.jp/en/", "fuente": "https://www.ip.mufg.jp/en/news/20190926_1"}, {"canal": "X/Twitter – CEO de Progmat publica alianzas en X (handle no obtenido)", "valor": null, "fuente": "https://gftnforum.jp/speakers/spkr6752-tatsuya-saito"}, {"canal": "LinkedIn company page Progmat (no se obtuvo URL en esta sesión)", "valor": null, "fuente": "https://www.ledgerinsights.com/japans-progmat-backed-by-big-3-banks-plans-tokenized-stocks-in-2026/"}, {"canal": "Buzón genérico: Corporate Communications for APAC – MUFG Bank — Buzón de prensa / comunicaciones corporativas Asia-Pacífico", "valor": "corpcomms@sg.mufg.jp", "fuente": "https://www.bk.mufg.jp/global/globalnetwork/asiapacific/anncts/index.html"}]'::jsonb, ruta_recomendada='1) Primer correo a Tatsuya Saito (Founder & CEO, Progmat): Progmat es la plataforma operativa (≈63% de emisiones ST en Japón; ~¥452bn en activos tokenizados migrados a Avalanche, migración completada jul-2026; PoC JGB repo en Canton anunciado el 13-ago-2026 con MUFG y Digital Asset). Proponer cross-listing/distribución secundaria de ST japoneses hacia Centroamérica y onboarding de RWA de Kabal (PSAD-0056) en Progmat; pedirle la intro interna a MUTB (accionista ancla y decisor del grupo). No hay email verificable: usar LinkedIn/X o el formulario de progmat.co.jp. 2) Intro cálida en paralelo: Securitize (MUIP invirtió en 2019 y opera Securitize Japan con MUFG), Digital Asset/Canton (socio del PoC agosto 2026) o Ava Labs/Avalanche y Datachain/TOKI (socios de la alianza feb-2026 y de la migración jul-2026; Datachain opera la stablecoin respaldada por MUTB). 3) Fallback: escribir a corpcomms@sg.mufg.jp (Corporate Communications APAC, único buzón público verificado en la página oficial de anuncios APAC de MUFG Bank) solicitando redirección a la unidad de activos digitales de MUTB; citar el comunicado del PoC del 13-ago-2026. 4) Nota: MUFG no tiene cobertura LatAm en activos digitales; encuadrar la propuesta como corredor Japón–Centroamérica (liquidez ancla / nota de colocación privada) y evitar vender servicios bancarios.',
 decisor=coalesce('Tatsuya Saito — Founder & CEO (Representative Director)',decisor), contacto_email=coalesce(contacto_email,null),
 notas=coalesce(notas,'')||E'\n[Contactos '||to_char(now(),'YYYY-MM-DD')||'] Programa: '||'Prueba de concepto de repo de JGB con liquidación on-chain vía Canton Network (2026); grupo dueño de la plataforma de tokenización Progmat.'||E'\n'||'Investigación automática 2026-10-19 (lote EXPLORE 2 del Liquidity Agent): agente de búsqueda + verificación adversarial de roles y correos; 15 búsquedas. Buzones genéricos movidos a canales_publicos: Corporate Communications for APAC – MUFG Bank. Todo correo con patron_no_verificado debe confirmarse antes de enviar.'
where id=(select id from p);
insert into liq_contactos (proveedor_id,nombre,cargo,area,ubicacion,linkedin,email,email_estado,rol,prioridad,por_que,fuente,notas)
select (select id from liq_proveedores where nombre='MUFG'), v.* from (values
('Tatsuya Saito','Founder & CEO (Representative Director)','Progmat, Inc. – plataforma de tokenización participada por MUTB/MUFG (accionista ancla)','Tokio, Japón',null,null,'desconocido','dueno_programa',1,'Dirige Progmat, plataforma ST líder en Japón (~63% de emisiones; ~¥452bn en activos tokenizados tras completar la migración a Avalanche en jul-2026) y pieza central del PoC JGB repo en Canton con MUFG/Digital Asset (13-ago-2026); ex-MUTB (sigue como adviser) y director de la Japan Security Token Association; anuncia alianzas personalmente y actúa como secretariado del consorcio de tokenización de JGB (may-2026).','https://gftnforum.jp/speakers/spkr6752-tatsuya-saito','Verificación: vigente en el cargo en 2025-2026 — bio oficial de ponente (gftnforum.jp / webx-asia.com) lo lista como Founder & CEO de Progmat, Adviser de MUTB y Director de JSTA; citado como CEO en la alianza con Ava Labs/Datachain (feb-2026), en la finalización de la migración a Avalanche (jul-2026, fintechobserver.com) y en el PoC JGB repo (ago-2026, mufg.jp). Corrección: la cifra de activos migrados reportada en jul-2026 es ~¥452bn, no ¥439.6bn. Fuente original (avax.network) no pudo abrirse desde esta sesión por bloqueo DNS; se sustituye por bio indexada. Sin patrón de email corroborado (progmat.co.jp; sugerencia de Clay first.last@mufg.jp sin evidencia), por eso email=null. Activo en X.'),
('Mitsubishi UFJ Trust and Banking (MUTB) – negocio de activos digitales','Unidad corporativa: custodio/fiduciario de activos digitales y accionista ancla de Progmat','MUTB – Digital Asset business / Corporate Communications','Tokio, Japón',null,null,'desconocido','canal_generico',4,'MUTB es el mayor proveedor de trust/custodia de activos digitales en Japón, principal accionista de Progmat y co-emisor del comunicado del PoC Canton (13-ago-2026, junto con MUFG Morgan Stanley Securities); los decisores del grupo sobre tokenización están aquí.','https://www.tr.mufg.jp/english/pressreleases/pdf/20260813_2.pdf','Verificación: el comunicado del 13-ago-2026 existe y está indexado (versiones en mufg.jp, tr.mufg.jp, bk.mufg.jp y sc.mufg.jp); cobertura de Ledger Insights, Markets Media y FS Tech confirma participantes (MUTB, MUFG Morgan Stanley Securities, Progmat, Digital Asset, Secured Finance) y encuadre en el Payment Innovation Project de la FSA. No se pudo identificar al responsable nominal de la unidad (fetch bloqueado por DNS); el comunicado incluye el contacto de Corporate Communications. Pedir a Saito la intro interna.'),
('MUFG Innovation Partners (MUIP)','Brazo de venture corporativo de MUFG – equipo de inversión y alianzas','MUFG Innovation Partners','Tokio, Japón',null,null,'desconocido','entrada',5,'Inversor en Securitize desde la ronda de US$14M de sep-2019 (junto con Santander InnoVentures y Nomura); canal natural para una intro cálida vía Securitize y puerta de entrada fintech del grupo.','https://www.ip.mufg.jp/en/news/20190926_1','Verificación: la URL de la fuente existe y está indexada (forma canónica con www.; también versión japonesa /ja/news/20190926_1); el comunicado cita a Nobutake Suzuki como CEO de MUIP en 2019 — NO verificado que siga en el cargo, por eso no se añade como contacto nominal. No se halló evidencia posterior a 2019 sobre la participación en Securitize; verificar vigencia del equipo antes de contactar. Página no pudo abrirse desde esta sesión por bloqueo DNS.')) as v(nombre,cargo,area,ubicacion,linkedin,email,email_estado,rol,prioridad,por_que,fuente,notas)
on conflict (proveedor_id, lower(nombre)) do update set cargo=excluded.cargo, area=excluded.area, ubicacion=excluded.ubicacion,
 linkedin=coalesce(excluded.linkedin,liq_contactos.linkedin), email=coalesce(excluded.email,liq_contactos.email), email_estado=excluded.email_estado,
 rol=excluded.rol, prioridad=excluded.prioridad, por_que=excluded.por_que, fuente=excluded.fuente, notas=excluded.notas;
